function initTabs(){const e=document.querySelectorAll(".tab-btn"),t=document.querySelectorAll(".tab-content");e.forEach(n=>{n.addEventListener("click",()=>{e.forEach(e=>{e.classList.remove("active")}),t.forEach(e=>e.classList.remove("active")),n.classList.add("active"),document.getElementById(n.getAttribute("data-tab")).classList.add("active")})})}function initQuiz(){const e=document.getElementById("ganga-quiz-form"),t=document.getElementById("quiz-result"),n={q1:"1",q2:"2"};e&&e.addEventListener("submit",a=>{a.preventDefault();let i=0;const o=new FormData(e);for(let[e,t]of o.entries())n[e]===t&&i++;const r=Object.keys(n).length;t.textContent=i===r?`🎉 Perfect! ${i}/${r}`:`You scored ${i}/${r}`,t.style.color=i===r?"green":"orange"})}function initGalleryModal(){const e=document.getElementById("gallery-modal"),t=document.getElementById("modal-title"),n=document.getElementById("modal-desc"),a=document.querySelector(".modal-close");document.querySelectorAll(".gallery-item").forEach(a=>{a.addEventListener("click",()=>{t.textContent=a.getAttribute("data-title"),n.textContent=a.getAttribute("data-desc"),e.classList.add("active")})}),a&&a.addEventListener("click",()=>e.classList.remove("active")),window.addEventListener("click",t=>{t.target===e&&e.classList.remove("active")})}function initScrollTop(){const e=document.getElementById("btn-scroll-top");e&&(window.addEventListener("scroll",()=>e.classList.toggle("visible",window.scrollY>300)),e.addEventListener("click",()=>window.scrollTo({top:0,behavior:"smooth"})))}function registerJourneyItems(){window.Journey&&window.Journey.registerSearchItems&&window.Journey.registerSearchItems("eastern-ganga-dynasty/index.html",[{id:"ganga-konark",title:"Konark Sun Temple",description:"UNESCO site built by Narasimhadeva I.",link:"eastern-ganga-dynasty/index.html#architecture"},{id:"ganga-jagannath",title:"Jagannath Puri",description:"Sacred Char Dham site.",link:"eastern-ganga-dynasty/index.html#architecture"}])}document.addEventListener("DOMContentLoaded",()=>{initTabs(),initQuiz(),initGalleryModal(),initScrollTop(),registerJourneyItems()});